type apiKeyRoleJoins[Q dialect.Joinable] struct {
	typ          string
	APIKey       modAs[Q, apiKeyColumns]
	RoleNameRole modAs[Q, roleColumns]
}

func (j apiKeyRoleJoins[Q]) aliasedAs(alias string) apiKeyRoleJoins[Q] {
	return buildAPIKeyRoleJoins[Q](buildAPIKeyRoleColumns(alias), j.typ)
}

func buildAPIKeyRoleJoins[Q dialect.Joinable](cols apiKeyRoleColumns, typ string) apiKeyRoleJoins[Q] {
	return apiKeyRoleJoins[Q]{
		typ: typ,
		APIKey: modAs[Q, apiKeyColumns]{
			c: APIKeys.Columns,
			f: func(to apiKeyColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, APIKeys.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.APIKeyID),
					))
				}

				return mods
			},
		},
		RoleNameRole: modAs[Q, roleColumns]{
			c: Roles.Columns,
			f: func(to roleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Roles.NameExpr().As(to.Alias())).On(
						to.Name.EQ(cols.RoleName),
					))
				}

				return mods
			},
		},
	}
}
